import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Три числа описывают каждую картинку, и люди постоянно их путают. Размеры, разрешение и вес файла звучат связанно, но каждое измеряет что-то своё.</p>\n<p>Путаница приводит к настоящим ошибкам. Люди покупают камеру с высокими мегапикселями и удивляются, почему печать выглядит мягко, или сжимают файл и удивляются, почему он всё равно не загружается.</p>\n<p>В этой статье мы распутаем три числа, покажем, как они связаны, и объясним, какое из них важно для веба, для печати и для соцсетей.</p>\n<h2 id=\"three-different-numbers\">Три числа — три значения</h2>\n<p>Размеры — это ширина и высота в пикселях, например 1920 на 1080. Они описывают, сколько пикселей содержит картинка, и больше ничего.</p>\n<p>Разрешение — это плотность этих пикселей, обычно в DPI или PPI. Оно говорит, сколько пикселей умещается в один дюйм, когда картинка печатается или отображается.</p>\n<p>Вес файла — это масса картинки на диске, обычно в килобайтах или мегабайтах. Он говорит, сколько места нужно файлу и как долго он будет скачиваться.</p>\n<p>Каждое число может меняться, а остальные — нет. Можно уменьшить файл, не трогая его размеров, и можно изменить DPI, не трогая ни одного пикселя.</p>\n<h2 id=\"dimensions-explained\">Размеры: количество пикселей</h2>\n<p>Размеры — самое конкретное из трёх чисел. Картинка 4000 на 3000 содержит 12 миллионов пикселей, расположенных в 4000 столбцов и 3000 строк.</p>\n<p>Размеры решают, насколько крупно картинка может показываться на экране без растяжения. Картинка шириной 400 пикселей, показанная шириной 1200 пикселей, должна придумать две трети своих пикселей, а придуманное выглядит размытым.</p>\n<p>Размеры также решают максимальный размер печати. Разделите ширину в пикселях на DPI печати, чтобы получить печатную ширину в дюймах, — значит, больше пикселей означает более крупный резкий отпечаток.</p>\n<p>Когда платформа отклоняет картинку за слишком маленький размер, она почти всегда проверяет размеры. Правила минимальной ширины — это правила в пикселях, и никакое сжатие или правка DPI их не удовлетворит.</p>\n<h2 id=\"resolution-explained\">Разрешение: DPI и PPI</h2>\n<p>Разрешение говорит, насколько плотно упакованы пиксели. Картинка с 300 DPI размещает 300 пикселей в каждом дюйме, а картинка с 72 DPI — только 72 в том же дюйме.</p>\n<p>На экране DPI по большей части игнорируется. Браузер показывает пиксели один за другим, поэтому картинка на 1000 пикселей выглядит одинаково при 72 DPI и при 300 DPI на мониторе.</p>\n<p>В печати DPI — это всё. Картинка на 3000 пикселей при 300 DPI печатается шириной 10 дюймов, а те же пиксели при 150 DPI печатаются шириной 20 дюймов с заметно более мягкими деталями.</p>\n<p>DPI — это метаданные, а не пиксели. Изменение его с помощью <a href=\"/ru/izmenit-dpi-izobrazheniya/\">инструмента изменения DPI изображения</a> переписывает небольшое число в заголовке файла и оставляет каждый пиксель нетронутым — поэтому изменение происходит без потерь.</p>\n<h2 id=\"file-size-explained\">Вес файла: масса на диске</h2>\n<p>Вес файла измеряется в килобайтах или мегабайтах и зависит от размеров, формата и сжатия. Большая картинка, сохранённая как несжатый PNG, может весить в десять раз больше той же картинки, сохранённой как сжатый JPG.</p>\n<p>Сжатие — самый большой рычаг влияния на вес файла. Понижение качества JPG с 90 до 70 может вдвое уменьшить файл, вообще не меняя размеров и DPI.</p>\n<p>Формат тоже важен. PNG хранит картинки без потерь, поэтому фотографии, сохранённые как PNG, тяжёлые. JPG и WebP отбрасывают данные, которые глаз едва замечает, поэтому для фотографий они куда легче.</p>\n<p>Вес файла решает успех загрузки и скорость страницы. Порталы ограничивают его в килобайтах, а браузеры скачивают его по сети, поэтому тяжёлый файл не проходит или задерживается, даже когда его размеры идеальны.</p>\n<h2 id=\"how-they-relate\">Как связаны три числа</h2>\n<p>Размеры задают потолок для всего остального. Картинка 4000 на 3000 может печататься крупно, показываться крупно и сжиматься многими способами, а картинка 400 на 300 не может хорошо делать ничего из этого.</p>\n<p>Разрешение переводит размеры в физический размер. Та же картинка на 3000 пикселей — это отпечаток 10 дюймов при 300 DPI и отпечаток 20 дюймов при 150 DPI, ведь DPI — просто коэффициент перевода пикселей в дюймы.</p>\n<p>Вес файла — это цена хранения пикселей. Больше пикселей стоит больше байтов, и меньшее сжатие тоже стоит больше байтов, поэтому самая тяжёлая картинка — большая и слабо сжатая.</p>\n<p>Думайте об этом как о треугольнике: размеры — это объём деталей, разрешение — плотность их упаковки, а вес файла — то, что вы платите за их хранение.</p>\n<h2 id=\"big-file-small-dimensions\">Почему большой файл может иметь маленькие размеры</h2>\n<p>Маленькая картинка, сохранённая как несжатый PNG, может весить несколько мегабайтов. Формат PNG хранит каждый пиксель точно, а в шумном фото много точной информации для хранения.</p>\n<p>Скриншоты — классический случай. Скриншот 1200 на 800, сохранённый как PNG, может весить 2 МБ, а тот же скриншот, сохранённый как JPG, весит 200 КБ, потому что JPG отбрасывает шум.</p>\n<p>Это удивляет людей, которые приравнивают вес файла к качеству. Тяжёлый PNG не лучше — он просто менее эффективно хранит те же пиксели.</p>\n<p>Когда портал отклоняет файл из-за веса, сначала проверьте формат. Преобразование фото из PNG в JPG часто решает проблему, вообще не трогая размеров.</p>\n<h2 id=\"small-file-huge-dimensions\">Почему маленький файл может иметь огромные размеры</h2>\n<p>Фото 6000 на 4000, сохранённое как JPG низкого качества, может весить меньше 1 МБ. Сильное сжатие отбрасывает большинство мелких деталей, оставляя большую сетку грубых пикселей.</p>\n<p>Размеры выглядят впечатляюще, но картинка — нет. Увеличьте её, и детали исчезнут, сменившись блочными артефактами и размазанными краями.</p>\n<p>Поэтому маркетплейсы проверяют размеры, а люди проверяют качество. Файл может пройти минимум по пикселям и всё равно выглядеть ужасно, когда покупатель увеличивает его.</p>\n<p>Для веба такая комбинация на самом деле полезна. Большое, сильно сжатое изображение-герой заполняет широкий экран и быстро загружается, ведь зритель никогда не увеличивает его настолько, чтобы увидеть повреждения.</p>\n<h2 id=\"print-math\">Математика печати: пиксели делить на DPI</h2>\n<p>Размер печати получается одним делением: пиксели делить на DPI равно дюймам. Картинка на 3000 пикселей при 300 DPI печатается шириной 10 дюймов, а при 150 DPI — шириной 20 дюймов.</p>\n<p>Стандарт качественной печати — 300 DPI. При такой плотности отдельные пиксели слишком малы, чтобы глаз различал их с расстояния чтения, поэтому отпечаток выглядит гладким.</p>\n<p>Крупноформатная печать смягчает стандарт. Постер, который смотрят с двух метров, хорошо выглядит при 150 DPI, а билборд, который видят с дороги, может опуститься до 50 DPI и ниже.</p>\n<p>Прежде чем отправлять файл в печать, выполните деление. Если результат меньше нужного размера, возьмите файл побольше или согласитесь на меньший отпечаток, ведь никакая настройка DPI не придумает недостающие пиксели.</p>\n<h2 id=\"screen-math\">Математика экрана: только пиксели, DPI игнорируется</h2>\n<p>Экраны не используют DPI так, как принтеры. Браузер отображает картинку пиксель в пиксель, поэтому картинка на 1000 пикселей занимает 1000 пикселей экрана независимо от её тега DPI.</p>\n<p>Поэтому картинка с 72 DPI и картинка с 300 DPI выглядят одинаково на сайте. Значение DPI — это метаданные, которые браузеры просто игнорируют.</p>\n<p>Экраны телефонов с высокой плотностью немного усложняют картину. Телефон с дисплеем 2x использует два физических пикселя на каждый CSS-пиксель, поэтому картинка на 1000 пикселей, показанная шириной 500 CSS-пикселей, всё равно выглядит резкой.</p>\n<p>Практическое правило для веба простое: сопоставьте размеры с размером показа и забудьте о DPI. Изображение-герой, показанное шириной 1200 пикселей, должно быть в файле примерно от 1200 до 2400 пикселей в ширину.</p>\n<h2 id=\"compression-and-file-size\">Сжатие и вес файла</h2>\n<p>Сжатие меняет вес файла, не меняя размеров и DPI. Оно переписывает данные пикселей более эффективно, отбрасывая детали, которые глаз вряд ли заметит.</p>\n<p>JPG и WebP — форматы с потерями: каждое сохранение отбрасывает ещё немного деталей. PNG — без потерь: он уменьшает файл, ничего не отбрасывая, поэтому фотографии в PNG остаются тяжёлыми.</p>\n<p>Настройки качества контролируют компромисс. JPG с качеством 90 сохраняет почти все видимые детали, а то же изображение с качеством 50 вдвое меньше по весу, с заметными повреждениями в градиентах и мелких текстурах.</p>\n<p>Используйте <a href=\"/ru/\">сжиматель изображений</a>, чтобы найти баланс для ваших картинок. Он позволяет увидеть результат и вес файла вместе, чтобы вы могли остановиться там, где экономия стоит повреждений.</p>\n<h2 id=\"choosing-dimensions-for-web\">Как выбрать размеры для веба</h2>\n<p>Для веба сопоставляйте размеры с наибольшим размером, в котором картинка когда-либо будет показана. Картинка, отображаемая шириной 800 пикселей, редко нуждается в файле больше 1600 пикселей, даже для экранов retina.</p>\n<p>Большие файлы загружаются медленнее и стоят мобильным пользователям трафика. Изображение-герой на 4000 пикселей, показанное шириной 1200 пикселей, тратит две трети своих пикселей при каждом просмотре страницы.</p>\n<p>Миниатюрам нужно куда меньше. Аватар на 200 пикселей, сохранённый как файл на 2000 пикселей, в десять раз тяжелее, чем нужно, а лишние пиксели невидимы.</p>\n<p>Отзывчивые изображения решают это правильно: отдавать маленький файл телефонам и большой — компьютерам. Но даже без этого подгонка файла под показ — самая большая победа в скорости.</p>\n<h2 id=\"choosing-dimensions-for-print\">Как выбрать размеры для печати</h2>\n<p>Для печати работайте в обратную сторону от физического размера. Умножьте нужные дюймы на 300, чтобы получить нужные пиксели: отпечаток 8 на 10 дюймов требует 2400 на 3000 пикселей.</p>\n<p>Всегда проверяйте и метаданные DPI. Файл с правильными пикселями, но тегом 72 DPI, будет воспринят некоторыми программами как огромный отпечаток, и макет окажется неверным, хотя пиксели в порядке.</p>\n<p>Задайте DPI правильно с помощью инструмента изменения DPI, после того как подтвердите число пикселей. Два числа вместе точно говорят типографии, чего вы хотите.</p>\n<p>Если пикселей не хватает, не увеличивайте и не надейтесь. Немного меньший отпечаток в полном качестве выглядит лучше, чем больший отпечаток из придуманных пикселей.</p>\n<h2 id=\"choosing-dimensions-for-social\">Как выбрать размеры для соцсетей и маркетплейсов</h2>\n<p>Соцсети агрессивно обрезают, поэтому соотношение важно не меньше числа пикселей. Портрет 1080 на 1350 заполняет ленту телефона, а квадрат 1080 на 1080 — безопасный выбор для всех лент.</p>\n<p>Маркетплейсы хотят крупные, почти квадратные картинки с местом для увеличения. Фото товара на 2000 пикселей на белом фоне удовлетворяет большинству минимумов и даёт покупателям чёткий вид.</p>\n<p>Превью видео — исключение, подтверждающее правило. Превью 1280 на 720 мало в пикселях, но должно читаться с первого взгляда, поэтому смелые формы важнее мелких деталей.</p>\n<p>Проверяйте каждую картинку с помощью <a href=\"/ru/proverit-razmery-izobrazheniya/\">проверки размеров изображения</a> перед загрузкой на новую платформу. Её пакетная таблица и проверки минимумов ловят сбои раньше платформы.</p>\n<h2 id=\"common-myths\">Частые мифы о размерах, разрешении и весе</h2>\n<p>Первый миф: более высокий DPI делает веб-картинку резче. Это не так, ведь браузеры игнорируют DPI. Резкость на экране решают только размеры в пикселях.</p>\n<p>Второй миф: больший файл — всегда лучшая картинка. Тяжёлый PNG и лёгкий JPG могут содержать одинаковые пиксели, и JPG почти всегда лучший файл для веба.</p>\n<p>Третий миф: мегапиксели решают качество печати. Это только половина истории; размер печати и DPI дополняют её, а картинка на 12 мегапикселей, напечатанная в размере постера, всё равно мягкая.</p>\n<p>Четвёртый миф: изменение DPI меняет картинку. Оно меняет число в заголовке, а не один пиксель, и картинка выглядит на экране ровно так же до и после.</p>\n<h2 id=\"quick-reference\">Быстрая шпаргалка: какое число важно и где</h2>\n<p>В вебе важнее всего размеры. Сопоставьте ширину в пикселях с размером показа, держите вес файла низким с помощью сжатия и полностью игнорируйте DPI.</p>\n<p>В печати размеры и DPI важны вместе. Умножьте свои дюймы на 300, чтобы получить нужные пиксели, а затем задайте тег DPI под них.</p>\n<p>Для загрузок и порталов важнее всего вес файла. Файл, который проходит минимум по пикселям, всё равно может быть отклонён за слишком много килобайтов.</p>\n<p>Вот пример из практики. Изображение-герой на сайте показывается шириной 1200 пикселей, а файл весит 3 МБ при размерах 4000 на 3000. Вы уменьшаете его до 2400 пикселей и сжимаете как JPG — вес падает до 300 КБ, а на экране разницы не видно. Размеры, разрешение и вес — три рычага, и вы только что использовали два из них.</p>\n<p>Тег DPI часто путают с качеством в Photoshop. Поле «разрешение» в диалоге размера изображения меняет только метаданные, пока вы не включите ресемплинг. Без ресемплинга пиксели не меняются, и картинка остаётся той же — меняется лишь число, которое прочитает типография.</p>\n<p>Для аватаров и миниатюр правило простое: храните файл чуть больше размера показа, но не в десять раз больше. Аватар на 100 пикселей из файла на 200 пикселей выглядит резким на retina-экранах и весит копейки, а тот же аватар из файла на 2000 пикселей — это просто потраченный трафик.</p>\n<p>Когда портал отклоняет файл за вес, не уменьшайте размеры первым делом. Сначала проверьте формат: фото в PNG часто весит в пять-десять раз больше того же фото в JPG. Конвертация решает проблему, а размеры и качество остаются прежними.</p>\n<p>Для печати всегда считайте от физического размера. Возьмите линейку, измерьте, каким будет отпечаток, умножьте на 300 — и вы знаете, сколько пикселей нужно. Этот расчёт занимает десять секунд и спасает от самой дорогой ошибки в работе с картинками.</p>\n<p>И последнее: не верьте ярлыкам «высокое разрешение» в описаниях файлов и стоков. Всегда смотрите на три числа — размеры в пикселях, тег DPI и вес файла. Только вместе они говорят, подойдёт ли картинка для вашей задачи.</p>\n<p>Для общего языка с командой запомните три определения: размеры — это количество пикселей, разрешение — это плотность упаковки, а вес файла — это цена хранения. Практические инструменты — в статье <a href=\"/ru/blog/kak-uznat-razmer-izobrazheniya-v-pikselyah/\">Как узнать размер изображения в пикселях: полное руководство</a> и в шагах в статье <a href=\"/ru/blog/kak-proverit-razmer-izobrazheniya/\">Как проверить размер изображения</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Меняет ли изменение DPI размеры изображения?","answer":"Нет. DPI — это метаданные, хранящиеся в заголовке файла, и его изменение не добавляет и не убирает пиксели. Картинка 3000 на 2000 остаётся 3000 на 2000, говорит ли её тег DPI 72 или 300. Меняется только размер печати, ведь размер печати — это пиксели, делённые на DPI."},{"question":"Почему мой файл картинки такой большой, хотя его размеры маленькие?","answer":"Вес больше решают формат и сжатие, чем размеры. Маленькое фото, сохранённое как несжатый PNG, может весить мегабайты, а те же пиксели, сохранённые как JPG, весят долю этого. Конвертируйте в JPG или WebP, чтобы уменьшить файл, не меняя размеров."},{"question":"Какие размеры нужны для резкой печати А4?","answer":"Лист А4 — примерно 8,3 на 11,7 дюйма, поэтому при 300 DPI нужно примерно 2500 на 3500 пикселей. Файл поменьше тоже можно напечатать на А4, но детали смягчатся, когда принтер растянет доступные пиксели по странице."},{"question":"Плохо ли качество картинки с 72 DPI?","answer":"Не обязательно. DPI важен только для печати, а тег 72 DPI ничего не говорит о самих пикселях. Картинка на 4000 пикселей с тегом 72 DPI — это качественный файл с неверными метаданными. Измените тег DPI, и размер печати исправится, не трогая ни одного пикселя."},{"question":"Как размеры влияют на скорость загрузки страницы?","answer":"Большие размеры обычно означают большие файлы, а большие файлы скачиваются дольше. Но связь не жёсткая: большая, сильно сжатая картинка может загружаться быстрее маленькой несжатой. Проверяйте и размеры, и вес файла, когда оптимизируете скорость."},{"question":"Можно ли увеличить размеры изображения без потери качества?","answer":"По сути нет. Увеличение придумывает пиксели, которых никогда не было, поэтому результат всегда мягче настоящего оригинала в высоком разрешении. ИИ-апскейлеры делают это лучше простого изменения размера, но они всё равно угадывают детали. Лучшее исправление — всегда более крупный исходный файл."}];
